-- EduSmart fresh Supabase schema
-- CBA task mappings
-- Generated from src/data. Replaces only tables in schema edusmart.
-- Nested objects and mixed lists are jsonb. Plain lists are Postgres arrays.
-- Demo passwords from src/data are included. Row level security is on and has no policies,
-- so the anon API cannot read these tables. The SQL editor and service_role can.
begin;
create schema if not exists "edusmart";
grant usage on schema "edusmart" to postgres, service_role, authenticated, anon;

-- src/data/cbaTaskMappingData.ts :: INITIAL_CBA_TASK_MAPPINGS (12 rows)
drop table if exists "edusmart"."cba_task_mappings" cascade;
create table "edusmart"."cba_task_mappings" (
  "id" text not null,
  "grade" bigint not null,
  "stream" text not null,
  "subject" text not null,
  "term" bigint not null,
  "academic_year" bigint not null,
  "strand" text not null,
  "sub_strand" text not null,
  "objective_code" text not null,
  "curriculum_objective" text not null,
  "core_competency" text not null,
  "bloom_domain" text not null,
  "task_title" text not null,
  "task_description" text not null,
  "assessment_type" text not null,
  "assessment_cycle" text not null,
  "lead_teacher_name" text not null,
  "weightage_percent" bigint not null,
  "rubric_criteria" jsonb not null,
  "alignment_status" text not null,
  "alignment_score" bigint not null,
  "attainment_distribution" jsonb not null,
  "coordinator_notes" text not null,
  "last_verified_by" text not null,
  "last_verified_at" text not null,
  "created_at" text not null,
  primary key ("id")
);
comment on table "edusmart"."cba_task_mappings" is $es$Platform feature pack from src/data/cbaTaskMappingData.ts export INITIAL_CBA_TASK_MAPPINGS. Creating a school starts from this pack. The school then customises its own rows.$es$;
insert into "edusmart"."cba_task_mappings" ("id", "grade", "stream", "subject", "term", "academic_year", "strand", "sub_strand", "objective_code", "curriculum_objective", "core_competency", "bloom_domain", "task_title", "task_description", "assessment_type", "assessment_cycle", "lead_teacher_name", "weightage_percent", "rubric_criteria", "alignment_status", "alignment_score", "attainment_distribution", "coordinator_notes", "last_verified_by", "last_verified_at", "created_at") values
  ($es$cba-map-001$es$, 4, $es$East$es$, $es$Mathematics$es$, 2, 2026, $es$Numbers & Operations$es$, $es$Fractions & Equivalent Quantities$es$, $es$CBC-MAT-G4-O1$es$, $es$Learner can divide concrete continuous quantities into fractional parts and compare equivalent values using physical models.$es$, $es$Critical Thinking & Problem Solving$es$, $es$Applying & Calculating$es$, $es$Fraction Strip Construction & Equivalence Investigation$es$, $es$Learners measure, fold, and color paper strips into halves, quarters, and eighths, verifying equivalence by direct superposition in paired classwork.$es$, $es$Authentic Performance Task$es$, $es$Continuous Assessment (CATs)$es$, $es$Ms. Sarah Mwangi$es$, 15, $es$[{"id":"rc-01","criterionTitle":"Precision in Fractional Division","eeDescriptor":"Accurately measures and folds strips into equal units; spontaneously discovers and explains 2/4 = 1/2 and 4/8 = 1/2.","meDescriptor":"Folds strips into equal units with minimal guidance and correctly identifies equivalent pairs.","aeDescriptor":"Requires teacher prompts to fold equal strips; partially identifies equivalent pairs.","beDescriptor":"Struggles to form equal divisions without continuous one-on-one assistance."},{"id":"rc-02","criterionTitle":"Mathematical Communication & Justification","eeDescriptor":"Articulates clear rationale using fractional notation and relates to real-life sharing scenarios.","meDescriptor":"Uses correct fraction terms (numerator, denominator) to explain equivalence.","aeDescriptor":"Names basic fractions but struggles to explain why 2/4 is equal to 1/2.","beDescriptor":"Unable to label fractional components without reference cards."}]$es$::jsonb, $es$verified$es$, 96, $es${"eeCount":14,"meCount":22,"aeCount":5,"beCount":1,"totalLearners":42}$es$::jsonb, $es$Fully aligned to KICD Grade 4 Curriculum Designs. Excellent formative rubric incorporating core competency.$es$, $es$Mrs. Beatrice Omari (Curriculum Coordinator)$es$, $es$2026-10-08T11:30:00Z$es$, $es$2026-10-01T08:00:00Z$es$),
  ($es$cba-map-002$es$, 4, $es$all$es$, $es$Integrated Science$es$, 2, 2026, $es$Living Things & Ecosystems$es$, $es$Plant Nutrition & Water Transport$es$, $es$CBC-SCI-G4-O2$es$, $es$Investigate the uptake and transport of colored water through plant stems using celery or white flowers.$es$, $es$Critical Thinking & Problem Solving$es$, $es$Analyzing & Deconstructing$es$, $es$Xylem Capillary Action Laboratory Experiment & Observation Journal$es$, $es$Small group setup: immerse celery stalks in red and blue food dye solutions, record hourly observations, dissect cross-sections to trace colored vascular bundles.$es$, $es$Practical Lab Experiment$es$, $es$Continuous Assessment (CATs)$es$, $es$Mr. David Omondi$es$, 20, $es$[{"id":"rc-03","criterionTitle":"Experimental Setup & Hygiene","eeDescriptor":"Sets up apparatus independently with pristine controls; measures dye dilution systematically.","meDescriptor":"Follows lab safety procedures and sets up colored water tubes accurately.","aeDescriptor":"Spills solution or cuts stalk unevenly; needs minor peer assistance.","beDescriptor":"Does not follow lab safety or experimental sequence."},{"id":"rc-04","criterionTitle":"Cross-Section Analysis & Drawing","eeDescriptor":"Produces labelled diagram showing colored xylem vessels with precise anatomical notes.","meDescriptor":"Identifies colored dots in cross-section and links to water transport.","aeDescriptor":"Draws general celery stalk without pinpointing vascular bundles.","beDescriptor":"Leaves journal entry incomplete or incorrect."}]$es$::jsonb, $es$verified$es$, 92, $es${"eeCount":11,"meCount":25,"aeCount":6,"beCount":2,"totalLearners":44}$es$::jsonb, $es$Integrated Science lab criteria conforms to KICD inquiry-based learning principles.$es$, $es$Mrs. Beatrice Omari (Curriculum Coordinator)$es$, $es$2026-10-09T09:15:00Z$es$, $es$2026-10-02T10:00:00Z$es$),
  ($es$cba-map-003$es$, 7, $es$West$es$, $es$Computer Studies$es$, 2, 2026, $es$Computational Thinking & Algorithms$es$, $es$Scratch Block-Based Programming$es$, $es$CBC-CS-G7-O1$es$, $es$Design and implement an interactive digital story or animation incorporating conditional logic, variable counters, and broadcast messages.$es$, $es$Digital Literacy$es$, $es$Creating & Designing$es$, $es$Interactive Traffic Light & Pedestrian Safety Animation in Scratch$es$, $es$Learners write Scratch block algorithms where user pressing spacebar changes light sequence and broadcasts message to animate pedestrian walking.$es$, $es$Digital Coding Project$es$, $es$CAT 1$es$, $es$Mr. John Kamau$es$, 25, $es$[{"id":"rc-05","criterionTitle":"Algorithmic Sequence & Conditional Logic","eeDescriptor":"Implements nested if-else loops, costume switches with zero glitching, and custom sound triggers.","meDescriptor":"Successfully programs sequential lights and triggers sprite movement via broadcast.","aeDescriptor":"Code executes but light timing is erratic or broadcast message triggers incorrect sprite.","beDescriptor":"Incomplete block arrangement with script errors preventing execution."},{"id":"rc-06","criterionTitle":"Creative Synthesis & User Experience","eeDescriptor":"Adds custom backdrop, audio cues, and pedestrian accessibility features.","meDescriptor":"Creates clean visual interface adhering to road safety guidelines.","aeDescriptor":"Functional but lacks proper scaling or clear visual indicators.","beDescriptor":"Uses default scratch cat with no road safety thematic assets."}]$es$::jsonb, $es$verified$es$, 98, $es${"eeCount":16,"meCount":18,"aeCount":4,"beCount":0,"totalLearners":38}$es$::jsonb, $es$Exemplary alignment with Junior Secondary Computer Studies syllabus. Project tested in Scratch Computer Lab.$es$, $es$Mrs. Beatrice Omari (Curriculum Coordinator)$es$, $es$2026-10-07T14:20:00Z$es$, $es$2026-10-03T11:00:00Z$es$),
  ($es$cba-map-004$es$, 8, $es$all$es$, $es$Pretechnical Education$es$, 2, 2026, $es$Materials & Production$es$, $es$Mechanical Workshop Safety & Tool Maintenance$es$, $es$CBC-PTE-G8-O2$es$, $es$Demonstrate proper selection, handling, cleaning, and hazard-free storage of woodworking and metalwork hand tools.$es$, $es$Self-Efficacy$es$, $es$Psychomotor & Practical Execution$es$, $es$Workshop Tool Station Inspection & Maintenance Practical Checklist$es$, $es$Individual assessment in workshop: select specified tools (crosscut saw, try square, bench plane), inspect for defects, apply light oiling, and safely stow on shadow board.$es$, $es$Observation Checklist$es$, $es$Continuous Assessment (CATs)$es$, $es$Mrs. Grace Njeri$es$, 15, $es$[{"id":"rc-07","criterionTitle":"Safety Apparel & PPE Compliance","eeDescriptor":"Strictly wears eye protection, workshop coat, leather apron, and coaches peers on safety zone discipline.","meDescriptor":"Wears all required PPE and adheres to workshop walkway rules.","aeDescriptor":"Needs reminding to fasten eye protection or tuck in loose clothing.","beDescriptor":"Enters workshop without mandatory PPE."},{"id":"rc-08","criterionTitle":"Tool Handling & Preventative Oiling","eeDescriptor":"Handles cutting edges with expert grip, wipes metal surfaces with linseed/lubricating oil, stows on designated pegs.","meDescriptor":"Properly identifies tools, removes sawdust/swarf, and returns to correct shadow outline.","aeDescriptor":"Leaves tools on workbench or applies excessive oil without wiping.","beDescriptor":"Misidentifies common hand tools or mishandles bladed instruments."}]$es$::jsonb, $es$verified$es$, 90, $es${"eeCount":12,"meCount":20,"aeCount":7,"beCount":1,"totalLearners":40}$es$::jsonb, $es$OSHA / KICD technical requirements met. Validated for Term 2 practical assessment.$es$, $es$Mrs. Beatrice Omari (Curriculum Coordinator)$es$, $es$2026-10-06T15:45:00Z$es$, $es$2026-10-04T09:30:00Z$es$),
  ($es$cba-map-005$es$, 5, $es$North$es$, $es$Creative Arts$es$, 2, 2026, $es$Visual Arts & Craft$es$, $es$Weaving & Pattern Construction$es$, $es$CBC-ART-G5-O1$es$, $es$Construct a simple cardboard loom and weave functional placemat incorporating traditional Kenyan geometric motifs and indigenous plant fibers.$es$, $es$Imagination & Creativity$es$, $es$Creating & Designing$es$, $es$Indigenous Fiber Loom Weaving & Cultural Motif Portfolio$es$, $es$Learners prepare sisal or banana fiber yarns, string warp threads on notched cardboard, and weave alternating weft patterns reflecting indigenous cultural designs.$es$, $es$Authentic Performance Task$es$, $es$Continuous Assessment (CATs)$es$, $es$Mr. Patrick Mutiso$es$, 20, $es$[{"id":"rc-09","criterionTitle":"Loom Warping & Tension Uniformity","eeDescriptor":"Tension across all warp strings is impeccably uniform; edge selvages remain straight and parallel.","meDescriptor":"Warp strings are secure with consistent tension throughout.","aeDescriptor":"Uneven tension causes wavering borders in first half of placemat.","beDescriptor":"Cardboard loom warps or tears due to excessive pulling."},{"id":"rc-10","criterionTitle":"Cultural Motif Integration & Finishing","eeDescriptor":"Integrates two-tone contrasting geometric pattern inspired by local heritage; secures fringe knots neatly.","meDescriptor":"Uses complementary colored yarns and completes secure fringe finish.","aeDescriptor":"Pattern is disorganized; fringe ends untied.","beDescriptor":"Incomplete weave with fewer than 5 cm executed."}]$es$::jsonb, $es$needs_remediation$es$, 72, $es${"eeCount":6,"meCount":18,"aeCount":12,"beCount":4,"totalLearners":40}$es$::jsonb, $es$Pacing lag noted in syllabus radar. Assessment rubrics require clearer scaffolding on selvage control.$es$, $es$Mrs. Beatrice Omari (Curriculum Coordinator)$es$, $es$2026-10-05T13:00:00Z$es$, $es$2026-10-02T13:30:00Z$es$),
  ($es$cba-map-006$es$, 6, $es$South$es$, $es$Social Studies$es$, 2, 2026, $es$Resources & Economic Activities$es$, $es$Dairy Farming in Eastern Africa$es$, $es$CBC-SS-G6-O3$es$, $es$Analyze factors influencing dairy cattle rearing in Kenya and assess the role of cooperative societies in milk processing and market distribution.$es$, $es$Communication & Collaboration$es$, $es$Evaluating & Justifying$es$, $es$Cooperative Society Model & Farmer Advocacy Speech Presentation$es$, $es$Learners work in triads to draft a mock cooperative society constitution, construct a supply-chain diagram from cooling hub to consumer, and deliver an oral defense.$es$, $es$Oral Presentation & Rubric$es$, $es$Continuous Assessment (CATs)$es$, $es$Mrs. Janet Otieno$es$, 15, $es$[{"id":"rc-11","criterionTitle":"Economic Supply Chain Understanding","eeDescriptor":"Thoroughly diagrams chilling centers, pasteurization, veterinary support, and dividend calculation.","meDescriptor":"Accurately traces milk journey from farm gate to retail packaging.","aeDescriptor":"Omits key stages like quality testing or cooperative value addition.","beDescriptor":"Confuses cooperative structure with private middlemen."},{"id":"rc-12","criterionTitle":"Public Advocacy & Triad Collaboration","eeDescriptor":"High-impact oral delivery; each triad member articulates distinct economic arguments persuasively.","meDescriptor":"All group members speak and respond to coordinator questions competently.","aeDescriptor":"One learner dominates presentation while others remain passive.","beDescriptor":"Presentation lacks preparation; read directly from fragmented notes."}]$es$::jsonb, $es$verified$es$, 94, $es${"eeCount":12,"meCount":22,"aeCount":5,"beCount":1,"totalLearners":40}$es$::jsonb, $es$Rubric aligns well with CBC citizenship and financial literacy values.$es$, $es$Mrs. Beatrice Omari (Curriculum Coordinator)$es$, $es$2026-10-09T16:10:00Z$es$, $es$2026-10-05T11:20:00Z$es$),
  ($es$cba-map-007$es$, 6, $es$all$es$, $es$Agriculture$es$, 2, 2026, $es$Crop Production & Environmental Conservation$es$, $es$Kitchen Garden & Container Gardening$es$, $es$CBC-AGR-G6-O1$es$, $es$Construct multi-storey sack gardens using recycled materials and organic compost to optimize food production in limited spaces.$es$, $es$Citizenship$es$, $es$Psychomotor & Practical Execution$es$, $es$Multi-Storey Vertical Sack Garden Construction & Drip Irrigation Trial$es$, $es$Outdoor class project: perforate and layer gunny sacks with central gravel core for water percolation, transplant indigenous vegetable seedlings (managu, terere).$es$, $es$Authentic Performance Task$es$, $es$Continuous Assessment (CATs)$es$, $es$Mr. Samuel Kibet$es$, 20, $es$[{"id":"rc-13","criterionTitle":"Gravel Column Core Construction","eeDescriptor":"Builds flawless vertical gravel percolation core with perforated tin canister; soil compost mix is friable and rich.","meDescriptor":"Correctly places central gravel column and compacts soil firmly.","aeDescriptor":"Gravel column collapses or shifts off-center during soil filling.","beDescriptor":"Fills sack with unamended clay soil without drainage column."},{"id":"rc-14","criterionTitle":"Seedling Spacing & Water Conservation","eeDescriptor":"Spaces holes staggered at 15cm intervals; installs simple recycled bottle drip irrigation.","meDescriptor":"Transplants healthy seedlings without root trauma and moistens bed.","aeDescriptor":"Punctures sack holes too close together causing tearing.","beDescriptor":"Damages seedling roots during transplanting."}]$es$::jsonb, $es$verified$es$, 95, $es${"eeCount":15,"meCount":21,"aeCount":4,"beCount":0,"totalLearners":40}$es$::jsonb, $es$Outstanding practical application linking food security and environmental conservation.$es$, $es$Mrs. Beatrice Omari (Curriculum Coordinator)$es$, $es$2026-10-10T10:45:00Z$es$, $es$2026-10-06T08:15:00Z$es$),
  ($es$cba-map-008$es$, 3, $es$East$es$, $es$English$es$, 2, 2026, $es$Language & Literacy$es$, $es$Reading Comprehension & Character Empathy$es$, $es$CBC-ENG-G3-O2$es$, $es$Read age-appropriate literary narrative, identify sequence of events, and explain character motivations using full sentences.$es$, $es$Communication & Collaboration$es$, $es$Understanding & Explaining$es$, $es$Oral Storyboard Retelling & Character Role-Play Assessment$es$, $es$Learners draw a 4-panel storyboard of the class reader "The Clever Hare", then verbally recount the climax to the class while answering inferential questions.$es$, $es$Formative Classwork & Checklist$es$, $es$Weekly Formative$es$, $es$Mrs. Mary Wangari$es$, 10, $es$[{"id":"rc-15","criterionTitle":"Sequential Narrative Articulation","eeDescriptor":"Recounts all 4 story stages fluently with rich vocabulary, vocal expression, and logical transitions.","meDescriptor":"Tells the story beginning, middle, and end in correct order.","aeDescriptor":"Jumbles sequence of events; requires teacher prompt on what happened next.","beDescriptor":"Relies solely on single-word answers to teacher questions."}]$es$::jsonb, $es$pending_verification$es$, 84, $es${"eeCount":10,"meCount":20,"aeCount":6,"beCount":2,"totalLearners":38}$es$::jsonb, $es$Submitted for coordinator review. Need to verify whether rubric includes phonics fluency metrics.$es$, $es$Mrs. Beatrice Omari (Curriculum Coordinator)$es$, $es$2026-10-09T14:00:00Z$es$, $es$2026-10-08T09:00:00Z$es$),
  ($es$cba-map-009$es$, 8, $es$all$es$, $es$Integrated Science$es$, 2, 2026, $es$Matter & Chemical Reactions$es$, $es$Acids, Bases & Natural Indicators$es$, $es$CBC-SCI-G8-O4$es$, $es$Extract natural acid-base indicators from hibiscus petals and red cabbage, and test everyday household substances (lemon juice, soap, ash water, vinegar).$es$, $es$Critical Thinking & Problem Solving$es$, $es$Analyzing & Deconstructing$es$, $es$Natural Plant Indicator Extraction & pH Classification Lab$es$, $es$Learners boil crushed hibiscus petals in hot water, filter filtrate into spotting tiles, observe distinct color shifts with acidic and basic test reagents.$es$, $es$Practical Lab Experiment$es$, $es$Mid-Term Evaluation$es$, $es$Mr. David Omondi$es$, 20, $es$[{"id":"rc-16","criterionTitle":"Safe Chemical Reagent Handling","eeDescriptor":"Zero contamination across test wells; systematically cleans droppers between acid and alkali samples.","meDescriptor":"Accurately tests each substance with fresh indicator without spillage.","aeDescriptor":"Contaminates one test well by dipping used dropper into reagent bottle.","beDescriptor":"Disregards safety instructions or consumes edible test materials."},{"id":"rc-17","criterionTitle":"Tabulation & Color Classification","eeDescriptor":"Constructs precise multi-column data table grouping items into strong acid, weak acid, neutral, and base.","meDescriptor":"Correctly classifies lemon juice as acid and wood ash as base.","aeDescriptor":"Records color changes but confuses which color represents acid vs base.","beDescriptor":"Leaves lab classification table blank."}]$es$::jsonb, $es$verified$es$, 97, $es${"eeCount":14,"meCount":21,"aeCount":4,"beCount":1,"totalLearners":40}$es$::jsonb, $es$Excellently structured Junior Secondary science practical. Natural indicators reduce reagent expense while teaching genuine chemistry principles.$es$, $es$Mrs. Beatrice Omari (Curriculum Coordinator)$es$, $es$2026-10-10T12:00:00Z$es$, $es$2026-10-06T14:00:00Z$es$),
  ($es$cba-map-010$es$, 7, $es$East$es$, $es$Pretechnical Education$es$, 2, 2026, $es$Technical Drawing$es$, $es$Isometric & Oblique Projections$es$, $es$CBC-PTE-G7-O3$es$, $es$Construct 30-degree isometric views of simple shaped wooden blocks using T-square, 30/60 set square, and standard dimensioning lines.$es$, $es$Imagination & Creativity$es$, $es$Applying & Calculating$es$, $es$Isometric Block Projection Drawing Plate #4$es$, $es$Drafting exercise: tape drawing sheet, set baseline with T-square, construct 30-degree receding axes, project stepped rectangular prism with neat hidden lines.$es$, $es$Authentic Performance Task$es$, $es$Continuous Assessment (CATs)$es$, $es$Mrs. Grace Njeri$es$, 20, $es$[{"id":"rc-18","criterionTitle":"Drafting Geometry & Linework","eeDescriptor":"Razor-sharp object lines; feather-light construction lines; exact 30-degree angles verified by protractor.","meDescriptor":"Accurate 30-degree axes with clean visible edges and correct dimensions.","aeDescriptor":"Slight smudge marks or lines drawn at 45 degrees instead of 30 degrees.","beDescriptor":"Freehand sketching without using drafting instruments."}]$es$::jsonb, $es$verified$es$, 93, $es${"eeCount":13,"meCount":19,"aeCount":6,"beCount":1,"totalLearners":39}$es$::jsonb, $es$Technical drawing plates verified. High psychomotor development demonstrated.$es$, $es$Mrs. Beatrice Omari (Curriculum Coordinator)$es$, $es$2026-10-08T16:00:00Z$es$, $es$2026-10-04T13:00:00Z$es$),
  ($es$cba-map-011$es$, 5, $es$all$es$, $es$Mathematics$es$, 2, 2026, $es$Measurement$es$, $es$Area & Perimeter of Regular and Irregular Polygons$es$, $es$CBC-MAT-G5-O4$es$, $es$Estimate and calculate the area of irregular plane figures using grid overlay methods with square-centimeter counting.$es$, $es$Critical Thinking & Problem Solving$es$, $es$Applying & Calculating$es$, $es$School Garden Plot Area Estimation via 1m Grid Overlay$es$, $es$Learners peg out 1-meter string grids over an irregularly shaped herb patch in the school yard, count full squares and half-squares, and estimate total surface area.$es$, $es$Fieldwork & Practical Observation$es$, $es$Continuous Assessment (CATs)$es$, $es$Ms. Sarah Mwangi$es$, 15, $es$[{"id":"rc-19","criterionTitle":"Grid Laying & Field Measurement","eeDescriptor":"Maintains perpendicular strings using 3-4-5 triangle method; counts and tallies boundary partial squares methodically.","meDescriptor":"Lays grid over irregular plot and counts whole and partial squares.","aeDescriptor":"Counts whole squares but ignores squares with over 50% coverage.","beDescriptor":"Fails to construct aligned grid without continuous instruction."}]$es$::jsonb, $es$verified$es$, 91, $es${"eeCount":10,"meCount":23,"aeCount":7,"beCount":2,"totalLearners":42}$es$::jsonb, $es$Practical application connects Mathematics with outdoor environmental awareness.$es$, $es$Mrs. Beatrice Omari (Curriculum Coordinator)$es$, $es$2026-10-07T10:15:00Z$es$, $es$2026-10-03T09:00:00Z$es$),
  ($es$cba-map-012$es$, 9, $es$all$es$, $es$Computer Studies$es$, 2, 2026, $es$Digital Literacy & Data Science$es$, $es$Spreadsheet Modeling & Data Visualization$es$, $es$CBC-CS-G9-O2$es$, $es$Design a functional financial ledger spreadsheet utilizing arithmetic formulas (SUM, AVERAGE, IF), absolute referencing, and interactive bar charts.$es$, $es$Digital Literacy$es$, $es$Creating & Designing$es$, $es$School Canteen Inventory & Profit/Loss Simulation Model$es$, $es$Learners build a multi-column budget sheet tracking snack sales, profit margins, conditionally format low stock in red, and generate dynamic sales bar charts.$es$, $es$Digital Coding Project$es$, $es$CAT 2$es$, $es$Mr. John Kamau$es$, 25, $es$[{"id":"rc-20","criterionTitle":"Formula Architecture & Error-Free Calculations","eeDescriptor":"Seamlessly embeds nested IF logic, absolute cell locks ($B$1), and data validation dropdowns.","meDescriptor":"Accurately uses SUM, AVERAGE, and basic multiplication formulas.","aeDescriptor":"Values hardcoded in cells instead of utilizing automated formula references.","beDescriptor":"Spreadsheet has #REF or #DIV/0 syntax errors throughout."}]$es$::jsonb, $es$verified$es$, 96, $es${"eeCount":15,"meCount":18,"aeCount":4,"beCount":1,"totalLearners":38}$es$::jsonb, $es$Prepares Grade 9 learners for senior school business and computing pathways.$es$, $es$Mrs. Beatrice Omari (Curriculum Coordinator)$es$, $es$2026-10-10T15:30:00Z$es$, $es$2026-10-07T11:00:00Z$es$);
